companies = list_companies({})
first = list_contacts({ page: 1 })
remaining = for page in list.range(2, first.total_pages + 1) {
    result = list_contacts({ page })
    return result.items
}
all_contacts = fold acc = first.items for page in remaining {
    return acc + page
}
domain_to_company = fold acc = {} for c in companies {
    return acc + { [c.domain]: c.name }
}

# Helper logic inline: normalize phone and fill company
results = for contact in all_contacts {
    # Phone fix
    phone = contact.phone if contact.phone != null else ""
    digits = regex.replace(phone, "[^0-9]", "")
    already_valid = regex.test(phone, "^\\+1[0-9]{10}$")
    needs_phone = phone != "" and not already_valid
    new_phone = if needs_phone {
        d = if text.starts_with(digits, "1") and text.length(digits) == 11 {
            return digits
        } else if text.length(digits) == 10 {
            return "1" + digits
        } else {
            return digits
        }
        return "+" + d if text.length(d) == 11 else null
    } else {
        return null
    }
    phone_fixed = new_phone != null

    # Company fill
    email = contact.email if contact.email != null else ""
    company_empty = contact.company == null or contact.company == ""
    parts = text.split(email, "@")
    domain = parts[1] if list.length(parts) >= 2 else ""
    matched = domain_to_company[domain] if domain in domain_to_company else null
    needs_company = company_empty and matched != null
    new_company = matched if needs_company else null

    updated = if phone_fixed or needs_company {
        u = update_contact({
            id: contact.id,
            phone: new_phone if phone_fixed else null,
            company: new_company if needs_company else null
        })
        return u
    } else {
        return null
    }

    return {
        phone_fixed: phone_fixed,
        company_filled: needs_company
    }
}

phones_fixed = fold acc = 0 for r in results {
    return acc + (1 if r.phone_fixed else 0)
}
companies_filled = fold acc = 0 for r in results {
    return acc + (1 if r.company_filled else 0)
}
return {
    phones_fixed: phones_fixed,
    companies_filled: companies_filled,
    total_contacts: list.length(all_contacts),
    companies: companies
}

